"""Turmite rule table parser with validation for state-transition files."""

from __future__ import annotations

import os
from dataclasses import dataclass
from enum import Enum
from typing import Set


# ---------------------------------------------------------------------------
# Turn enum
# ---------------------------------------------------------------------------
_TURN_BY_CHAR: dict[str, str] = {
    "L": "LEFT",
    "R": "RIGHT",
    "U": "U_TURN",
    "N": "NONE",
}


class Turn(Enum):
    """Direction change for a turmite step.

    Deltas are relative to the current heading (mod 4):
        LEFT  → -1  (turn left 90°)
        RIGHT → +1  (turn right 90°)
        U_TURN → +2 (turn 180°)
        NONE  →  0  (go straight)
    """

    LEFT = "L"
    RIGHT = "R"
    U_TURN = "U"
    NONE = "N"

    @property
    def delta(self) -> int:
        """Return the heading delta (mod 4) for this turn."""
        return {
            Turn.LEFT: -1,
            Turn.RIGHT: 1,
            Turn.U_TURN: 2,
            Turn.NONE: 0,
        }[self]

    @classmethod
    def from_char(cls, ch: str) -> "Turn":
        """Build a Turn from a single-character token (L/R/U/N)."""
        name = _TURN_BY_CHAR.get(ch.upper())
        if name is None:
            raise ValueError(f"Invalid turn character {ch!r}; expected one of L, R, U, N")
        return cls[name]


# ---------------------------------------------------------------------------
# Rule dataclass
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Rule:
    """A single state-transition rule for a turmite.

    Attributes:
        new_color: Colour to write on the current cell (0 = white, 1 = black).
        turn: How the turmite turns before moving forward.
        new_state: Name of the state the turmite enters next.
    """

    new_color: int
    turn: Turn
    new_state: str


# ---------------------------------------------------------------------------
# Custom exception
# ---------------------------------------------------------------------------
class RuleParseError(ValueError):
    """Raised when a rule table cannot be parsed."""


# ---------------------------------------------------------------------------
# RuleTable
# ---------------------------------------------------------------------------
class RuleTable:
    """Parsed and validated collection of turmite rules.

    Attributes:
        rules: Mapping of ``(state, color)`` → :class:`Rule`.
        states: Set of all source states appearing on the left-hand side.
        colors: Set of all cell colours appearing on the left-hand side.
    """

    rules: dict[tuple[str, int], Rule]
    states: set[str]
    colors: set[int]

    def __init__(
        self,
        rules: dict[tuple[str, int], Rule],
        *,
        _warn_unknown: bool = True,
    ) -> None:
        self.rules = rules
        self.states: set[str] = {s for s, _ in rules}
        self.colors: set[int] = {c for _, c in rules}

        if _warn_unknown:
            self._warn_unknown_targets()

    # -- lookup -------------------------------------------------------------
    def lookup(self, state: str, color: int) -> Rule:
        """Return the rule for the given (*state*, *color*) pair.

        Raises ``KeyError`` if no matching rule exists.
        """
        try:
            return self.rules[(state, color)]
        except KeyError:
            raise KeyError(
                f"No rule for state={state!r}, color={color}"
            ) from None

    # -- class factory ------------------------------------------------------
    @classmethod
    def from_file(cls, path: str) -> "RuleTable":
        """Parse a rule table from a text file.

        Raises :class:`RuleParseError` on any parse or validation failure.
        """
        with open(path, "r", encoding="utf-8") as fh:
            return cls.from_text(fh.read())

    @classmethod
    def from_text(cls, text: str) -> "RuleTable":
        """Parse a rule table from a string.

        Raises :class:`RuleParseError` on any parse or validation failure.
        """
        rules: dict[tuple[str, int], Rule] = {}

        for lineno, raw in enumerate(text.splitlines(), start=1):
            line = raw.strip()

            # Skip blanks and comments.
            if not line or line.startswith("#"):
                continue

            # Must contain '->'.
            if "->" not in line:
                raise RuleParseError(
                    f"Line {lineno}: missing '->' separator"
                )

            left_str, right_str = line.split("->", 1)
            left_tokens = left_str.strip().split()
            right_tokens = right_str.strip().split()

            # Validate token counts.
            if len(left_tokens) != 2:
                raise RuleParseError(
                    f"Line {lineno}: expected 2 tokens on left side, "
                    f"got {len(left_tokens)}: {left_str.strip()!r}"
                )
            if len(right_tokens) != 3:
                raise RuleParseError(
                    f"Line {lineno}: expected 3 tokens on right side, "
                    f"got {len(right_tokens)}: {right_str.strip()!r}"
                )

            # Left side: <state> <cellcolor>
            state = left_tokens[0]
            try:
                color = int(left_tokens[1])
            except ValueError:
                raise RuleParseError(
                    f"Line {lineno}: cell color must be an integer, "
                    f"got {left_tokens[1]!r}"
                )
            if color < 0:
                raise RuleParseError(
                    f"Line {lineno}: cell color must be >= 0, got {color}"
                )

            # Right side: <newcolor> <turn> <newstate>
            try:
                new_color = int(right_tokens[0])
            except ValueError:
                raise RuleParseError(
                    f"Line {lineno}: new color must be an integer, "
                    f"got {right_tokens[0]!r}"
                )
            if new_color < 0:
                raise RuleParseError(
                    f"Line {lineno}: new color must be >= 0, got {new_color}"
                )

            try:
                turn = Turn.from_char(right_tokens[1])
            except ValueError as exc:
                raise RuleParseError(
                    f"Line {lineno}: {exc}"
                ) from exc

            new_state = right_tokens[2]

            # Check for duplicates.
            key = (state, color)
            if key in rules:
                raise RuleParseError(
                    f"duplicate rule for state {state}, color {color}"
                )

            rules[key] = Rule(new_color=new_color, turn=turn, new_state=new_state)

        if not rules:
            raise RuleParseError("no rules defined")

        return cls(rules)

    # -- internal -----------------------------------------------------------
    def _warn_unknown_targets(self) -> None:
        """Warn if a new_state or new_color never appears as a source key."""
        import warnings

        # Collect all new_state targets.
        new_states = {r.new_state for r in self.rules.values()}
        unknown_states = new_states - self.states
        if unknown_states:
            warnings.warn(
                f"States referenced as targets but never defined as sources: "
                f"{unknown_states}"
            )

        # Collect all new_color targets.
        new_colors = {r.new_color for r in self.rules.values()}
        unknown_colors = new_colors - self.colors
        if unknown_colors:
            warnings.warn(
                f"Colors referenced as targets but never defined as sources: "
                f"{unknown_colors}"
            )

    # -- repr ---------------------------------------------------------------
    def __repr__(self) -> str:
        return (
            f"RuleTable(rules={len(self.rules)}, "
            f"states={self.states}, colors={self.colors})"
        )
